13	/// Owns the one broadcast `biometricEnabled` stream Story 2.4's AD-14-style
14	/// seam requires. Covers the I/O & Edge-Case Matrix exactly:
15	/// - boot fetch resolves `false`/`true` -> [currentBiometricEnabled]/
16	///   [biometricEnabledStream] updated to that value.
17	/// - boot fetch fails -> swallowed, [currentBiometricEnabled] unchanged.
18	/// - [setBiometricEnabled] -> flips immediately (optimistic), PATCH fires;
19	///   success leaves it flipped, failure reverts it and returns `Left`.
20	class AccountSettingsRepositoryImpl implements AccountSettingsRepository {
21	  AccountSettingsRepositoryImpl({
22	    required AccountRemoteDataSource remoteDataSource,
23	  }) : _remoteDataSource = remoteDataSource;
