173	      // superseding call owns `_currentValue` from here on.
174	      return left(
175	        const Failure.malformedResponse(
176	          message: AccountSettingsRepository.supersededMessage,
177	        ),
178	      );
179	    }
180	    return result.match((failure) {
181	      // Revert on failure — the caller surfaces `failure.message` inline.
182	      _emit(previous);
183	      return left(failure);
184	    }, (_) => right(unit));
185	  }
186	
187	  @override
188	  Future<void> dispose() async {
189	    await _controller.close();
190	  }
191	}
